-- =====================================================================================
-- V2 - Identifier generation
--
-- Identifiers are generated by explicit sequences (never IDENTITY, never app-side UUIDs)
-- so the database is the only authority for keys:
--   * sequence values are unique and generated without a round trip to the application;
--   * gaps are expected and harmless: a ROLLBACK burns the numbers already fetched by
--     the session, and CACHE pre-allocates values. Nothing in the domain depends on
--     contiguity or on "no gaps" ordering;
--   * NOORDER keeps generation scalable on RAC (values are not globally ordered);
--   * CACHE avoids recursive SQL on the sequence for every write. Losing cached values
--     on instance crash only produces gaps.
-- Ordering of the statement is therefore NOT given by the id: the API sorts by
-- (occurred_at DESC, id DESC), where occurred_at is a TIMESTAMP WITH TIME ZONE.
-- =====================================================================================

CREATE SEQUENCE seq_wallet
    START WITH 1000
    INCREMENT BY 1
    CACHE 20
    NOORDER
    NOCYCLE;

CREATE SEQUENCE seq_wallet_transaction
    START WITH 1
    INCREMENT BY 1
    CACHE 50
    NOORDER
    NOCYCLE;
